import type {TextProps} from '@primer/react'
import {Text} from '@primer/styled-react'
import type {SxProp} from '@primer/styled-react'

export function NoBreak({sx, ...props}: TextProps & {sx?: SxProp}) {
  return <Text sx={{whiteSpace: 'nowrap', ...sx}} {...props} />
}

try{ NoBreak.displayName ||= 'NoBreak' } catch {}